// 01 Normalize — 把 Form 單筆 / Sheets 多筆統一成同一 JSON schema
// 正規化後 schema：
//   { projectName, targetUrl, localPath, phpVersion, scopes[], credentials{...}, notifyEmail, warnings[] }

const src = $json;

// multiSelect 在 Form 可能是陣列或逗號分隔字串；Sheets 一定是字串
function parseScopes(raw) {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  return String(raw).split(',').map(s => s.trim()).filter(Boolean);
}

const ALL = ['precheck','static','unit','api-test','db-test','links','ssl','trivy','lighthouse','e2e','nuclei','security','stress','monkey','summary'];
const REMOTE = ['precheck','ssl','security','nuclei','stress','lighthouse','links','monkey','summary'];
const LOCAL  = ['static','unit','trivy','db-test','summary'];

function expandPresets(list) {
  const out = new Set();
  for (const s of list) {
    if (s === 'ALL' || s === 'all') ALL.forEach(x => out.add(x));
    else if (s === 'REMOTE_ONLY' || s === 'remote-only') REMOTE.forEach(x => out.add(x));
    else if (s === 'LOCAL_ONLY' || s === 'local-only') LOCAL.forEach(x => out.add(x));
    else out.add(s);
  }
  return [...out];
}

const scopes = expandPresets(parseScopes(src.scopes));

// 組 .env 內容（給 write-project-config.sh 的 env_b64）
const envLines = [];
if (src.adminUsername || src.admin_username) envLines.push(`ADMIN_USERNAME=${src.adminUsername || src.admin_username}`);
if (src.adminPassword || src.admin_password) envLines.push(`ADMIN_PASSWORD=${src.adminPassword || src.admin_password}`);
if (src.e2eUsername || src.e2e_username) envLines.push(`E2E_USERNAME=${src.e2eUsername || src.e2e_username}`);
if (src.e2ePassword || src.e2e_password) envLines.push(`E2E_PASSWORD=${src.e2ePassword || src.e2e_password}`);
// Sheets 多身分（USER1~USER5）
for (let i = 1; i <= 5; i++) {
  const u = src[`user${i}_username`];
  const p = src[`user${i}_password`];
  const l = src[`user${i}_label`];
  if (u) envLines.push(`USER${i}_USERNAME=${u}`);
  if (p) envLines.push(`USER${i}_PASSWORD=${p}`);
  if (l) envLines.push(`USER${i}_LABEL=${l}`);
}

const envContent = envLines.join('\n') + (envLines.length ? '\n' : '');
const envB64 = Buffer.from(envContent, 'utf-8').toString('base64');

return {
  projectName: (src.projectName || src.project_name || '').trim(),
  targetUrl: (src.targetUrl || src.target_url || '').trim(),
  localPath: (src.localPath || src.local_path || '').trim(),
  phpVersion: (src.phpVersion || src.php_version || '8.1').trim(),
  scopes,
  scopesCsv: scopes.join(','),
  envB64,
  notifyEmail: (src.notifyEmail || src.notify_email || '').trim(),
  enabled: src.enabled === undefined || src.enabled === '' || String(src.enabled).toLowerCase() === 'true',
  warnings: []
};

// 03 Precheck & Warning — 必填檢查 + 非致命欄位缺失記 warning
// 致命：projectName / targetUrl 空 → throw，該 item 失敗但 SplitInBatches 繼續下一 item
// 非致命：local_path / 帳密 缺 → append warning，相關 scope 從 list 移除

const d = $json;
const warnings = [];

// 致命
if (!d.projectName) throw new Error('❌ project_name 未提供，整列拒絕');
if (!d.targetUrl) throw new Error('❌ target_url 未提供，整列拒絕');

// 非致命
const scopes = new Set(d.scopes || []);

// local_path 檢查：n8n 在容器內可能看不到宿主路徑，這裡只檢查字串是否提供
// 真實的目錄存在檢查由 write-project-config.sh + run-project.sh 負責，也會再 append warning
if (!d.localPath) {
  warnings.push('⚠ local_path 未設 → 將跳過 static/unit/trivy/db-test');
  ['static','unit','trivy','db-test'].forEach(s => scopes.delete(s));
}

// target_url 非 https → skip ssl
if (!d.targetUrl.startsWith('https://')) {
  if (scopes.has('ssl')) {
    warnings.push('⚠ target_url 非 https → 跳過 SSL 掃描');
    scopes.delete('ssl');
  }
}

// admin 帳密檢查（給 api-test / auth-test）
const hasAdmin = d.envB64 && Buffer.from(d.envB64, 'base64').toString('utf-8').match(/ADMIN_USERNAME=\S/);
if (!hasAdmin) {
  if (scopes.has('api-test') || scopes.has('auth-test')) {
    warnings.push('⚠ 未提供 admin 帳密 → API/Auth 測試會 skip');
    // 不強制移除 scope（讓 run-project.sh 自己處理，也會記 warning）
  }
}

// e2e 帳密（非致命，降級為未登入）
const hasE2e = d.envB64 && Buffer.from(d.envB64, 'base64').toString('utf-8').match(/E2E_USERNAME=\S/);
if (!hasE2e && scopes.has('e2e')) {
  warnings.push('⚠ 未提供 E2E 帳密 → e2e 將只跑公開頁面');
}

const finalScopes = [...scopes];

return {
  ...d,
  scopes: finalScopes,
  scopesCsv: finalScopes.join(','),
  warnings: [...(d.warnings || []), ...warnings]
};

// 從 04 stdout 最後一行取 registry path（write-project-config.sh 最後一行輸出）
const lines = ($json.stdout || '').trim().split('\n').filter(Boolean);
const registryPath = lines[lines.length - 1] || '';
if (!registryPath) throw new Error('write-project-config.sh 未回傳 registry path');
// 把原本 03 的資料合回來（SplitInBatches + executeCommand 會只剩 stdout）
const upstream = $('03 Precheck & Warning').itemMatching($itemIndex).json;
return { ...upstream, registryPath };

// 05 後把 n8n precheck warnings 先寫入 reports/<name>/warnings.txt
// run-project.sh 結束時會 append 自己的 warning，但會覆寫——
// 所以這裡改用 mkdir 建立 reports 目錄，n8n warnings 透過環境變數帶給 06，由 run-project.sh 合併
const upstream = $('04.5 Extract Registry Path').itemMatching($itemIndex).json;
return upstream;

// 08 Parse Results — 解析 07 的 JSON stdout，合併 06 pre-existing warnings
const upstream = $('05.5 Pass-through').itemMatching($itemIndex).json;
let parsed = {};
try {
  parsed = JSON.parse($json.stdout);
} catch (e) {
  return {
    projectName: upstream.projectName,
    notifyEmail: upstream.notifyEmail,
    parseError: e.message,
    rawStdout: ($json.stdout || '').slice(0, 500),
    warnings: upstream.warnings || []
  };
}
// parsed.warnings 已含 run-project.sh 寫的 warnings.txt 內容；再加 n8n 階段的 warnings（若還沒進檔）
const mergedWarnings = [...new Set([...(parsed.warnings || []), ...(upstream.warnings || [])])];
// overallScore：用 lighthouse.avg.performance 或 lighthouse perf 作為代理；若沒則 null
const overallScore = parsed.lighthouse?.avg?.performance ?? null;
return {
  ...parsed,
  projectName: upstream.projectName,
  notifyEmail: upstream.notifyEmail,
  overallScore,
  warnings: mergedWarnings
};

